package utils

import (
	"encoding/json"
	"net/http"
	"reflect"
	"testing"
	"time"
)

// 152 个预期值来自原 ELF 隔离指令执行，不由待测 Go 实现生成。
func TestOriginalMachineHeaders(t *testing.T) {
	oldChrome, oldEdge, oldCH, oldEH := chromeUA, edgeUA, chromeCHUA, edgeCHUA
	defer func() { chromeUA, edgeUA, chromeCHUA, edgeCHUA = oldChrome, oldEdge, oldCH, oldEH }()
	chromeUA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/144.0.0.0 Safari/537.36"
	edgeUA = chromeUA + "Edg/144.0.0.0"
	chromeCHUA, edgeCHUA = getGreasedChUa(144, "chrome"), getGreasedChUa(144, "edge")
	var cases []struct {
		Kind        string          `json:"kind"`
		Version     int             `json:"version"`
		Browser     string          `json:"browser"`
		RequestKind string          `json:"request_kind"`
		Input       http.Header     `json:"input"`
		Expected    json.RawMessage `json:"expected"`
	}
	if err := json.Unmarshal([]byte(machineHeaderGoldens), &cases); err != nil {
		t.Fatal(err)
	}
	for i, c := range cases {
		if c.Kind == "chua" {
			var want string
			if err := json.Unmarshal(c.Expected, &want); err != nil {
				t.Fatal(err)
			}
			if got := getGreasedChUa(c.Version, c.Browser); got != want {
				t.Errorf("case %d CH-UA got %q want %q", i, got, want)
			}
		} else {
			var want http.Header
			if err := json.Unmarshal(c.Expected, &want); err != nil {
				t.Fatal(err)
			}
			TryDefaultHeadersWith(c.Input, c.RequestKind)
			if !reflect.DeepEqual(c.Input, want) {
				t.Errorf("case %d headers got %#v want %#v", i, c.Input, want)
			}
		}
	}
}

func TestVersionDateBoundary(t *testing.T) {
	start := time.Date(2026, 1, 13, 0, 0, 0, 0, time.UTC)
	for _, seed := range []int64{0, 1, 177, 255, -1} {
		for _, tt := range []struct {
			at   time.Time
			want int
		}{{start.Add(-time.Second), 143}, {start, 143}, {start.Add(time.Nanosecond), 144}} {
			if got := chromeVersionAt(tt.at, seed); got != tt.want {
				t.Fatalf("seed %d at %s got %d want %d", seed, tt.at, got, tt.want)
			}
		}
	}
}

func TestOriginalNegativeAndNilPanics(t *testing.T) {
	for _, f := range []func(){func() { getGreasedChUa(-1, "chrome") }, func() { TryDefaultHeadersWith(nil, "fetch") }} {
		func() {
			defer func() {
				if recover() == nil {
					t.Error("原越界/空 map 分支应 panic")
				}
			}()
			f()
		}()
	}
}

